class Mapping:
 def __init__(self): self.data={}
 def __getitem__(self,key): return self.data[key]
 def __setitem__(self,key,value):
  print("set",key,value)
  self.data[key]=value
 def __delitem__(self,key):
  print("del",key)
  del self.data[key]
m=Mapping()
exec("x=7\ny=x+9\ndel x",{},m)
print(m.data["y"])

class Mapping:
 def __getitem__(self,key): raise KeyError(key)
 def __setitem__(self,key,value):
  print("set",key)
  raise ValueError("mapping")
try: exec("x=7",{},Mapping())
except ValueError as e: print(str(e))

class D(dict):
 def __getitem__(self,key):
  print("get",key)
  return dict.__getitem__(self,key)
 def __setitem__(self,key,value):
  print("set",key,value)
  dict.__setitem__(self,key,value)
 def __delitem__(self,key):
  print("del",key)
  dict.__delitem__(self,key)
g=D()
exec("x=7\ny=x+9\ndel x",g)
print(dict.__getitem__(g,"y"))

class D(dict):
 def __setitem__(self,key,value): raise ValueError("override")
g=D()
exec("global x\nx=7",g,{})
print(dict.__getitem__(g,"x"))

